// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.fees;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FeeDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        FeeService fees = new FeeService();

        // FLAT fee → ATM withdrawal: fixed Rs.20 regardless of amount.
        fees.applyFee(rajesh, ChargeType.FLAT, new BigDecimal("5000"));
        // PERCENT fee → international transfer: 2% of amount.
        fees.applyFee(priya, ChargeType.PERCENT, new BigDecimal("100000"));
        // FREE → internal transfer between own accounts: no fee.
        fees.applyFee(rajesh, ChargeType.FREE, new BigDecimal("30000"));
    }
}

// ─── Would be in ChargeType.java in a real project ───
enum ChargeType {
    // Each constant supplies its own body = constant-specific class body.
    FLAT {
        @Override public BigDecimal compute(BigDecimal amount) {
            return new BigDecimal("20.00");          // fixed fee
        }
    },
    PERCENT {
        @Override public BigDecimal compute(BigDecimal amount) {
            return amount.multiply(new BigDecimal("0.02"))
                         .setScale(2, RoundingMode.HALF_UP); // 2%
        }
    },
    FREE {
        @Override public BigDecimal compute(BigDecimal amount) {
            return BigDecimal.ZERO.setScale(2);      // no fee
        }
    };

    // Abstract method forces EVERY constant to implement it (compiler-checked).
    public abstract BigDecimal compute(BigDecimal amount);
}

// ─── Would be in Account.java in a real project ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }

    void debit(BigDecimal amount)  { this.balance = this.balance.subtract(amount); }
    void credit(BigDecimal amount) { this.balance = this.balance.add(amount); }

    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in FeeService.java in a real project ───
class FeeService {
    private static final Logger log = Logger.getLogger("BankLog");

    void applyFee(Account account, ChargeType type, BigDecimal amount) {
        // Polymorphic dispatch: no switch, the constant knows its own rule.
        BigDecimal fee = type.compute(amount);
        account.debit(fee);
        log.info(() -> type + " fee on Rs." + amount + " = Rs." + fee
                + " | " + account.getHolderName() + " balance Rs." + account.getBalance());
    }
}
